import{_ as a}from"./chunks/ark_g5_rtk_gps.DPjTCsIl.js";import{_ as t,o as r,c as i,al as n}from"./chunks/framework.7vp1BMOE.js";const m=JSON.parse('{"title":"ARK G5 RTK HEADING GPS","description":"","frontmatter":{},"headers":[],"relativePath":"uk/dronecan/ark_g5_rtk_heading_gps.md","filePath":"uk/dronecan/ark_g5_rtk_heading_gps.md"}'),l={name:"uk/dronecan/ark_g5_rtk_heading_gps.md"};function o(s,e,h,c,d,u){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="ark-g5-rtk-heading-gps" tabindex="-1">ARK G5 RTK HEADING GPS <a class="header-anchor" href="#ark-g5-rtk-heading-gps" aria-label="Permalink to &quot;ARK G5 RTK HEADING GPS&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This GPS module is made in the USA and NDAA compliant.</p></div><p><a href="https://arkelectron.com/product/ark-g5-rtk-gps/" target="_blank" rel="noreferrer">ARK G5 RTK HEADING GPS</a> is a <a href="./">DroneCAN</a> quad-band dual antenna <a href="./../gps_compass/rtk_gps">RTK GPS</a> that additionally provides vehicle yaw information from GPS.</p><p>The module incorporates the <a href="https://www.septentrio.com/en/products/gnss-receivers/gnss-receiver-modules/mosaic-G5-P3H" target="_blank" rel="noreferrer">Septentrio mosaic-G5 P3H Ultra-compact high-precision GPS/GNSS receiver module with heading capability</a>, magnetometer, barometer, IMU, and buzzer module.</p><p><img src="'+a+'" alt="ARK G5 RTK HEADING GPS"></p><h2 id="де-купити" tabindex="-1">Де купити <a class="header-anchor" href="#де-купити" aria-label="Permalink to &quot;Де купити&quot;">​</a></h2><p>Замовте цей модуль з:</p><ul><li><a href="https://arkelectron.com/product/ark-g5-rtk-heading-gps/" target="_blank" rel="noreferrer">ARK Electronics</a> (US)</li></ul><h2 id="характеристики-обладнання" tabindex="-1">Характеристики обладнання <a class="header-anchor" href="#характеристики-обладнання" aria-label="Permalink to &quot;Характеристики обладнання&quot;">​</a></h2><ul><li><a href="./">DroneCAN</a> RTK GNSS, Magnetometer, Barometer, IMU, and Buzzer Module</li><li><a href="./../dronecan/#firmware-update">Dronecan Firmware Updating</a></li><li>Датчики <ul><li><a href="https://www.septentrio.com/en/products/gnss-receivers/gnss-receiver-modules/mosaic-G5-P3H" target="_blank" rel="noreferrer">Septentrio mosaic-G5 P3H Ultra-compact high-precision GPS/GNSS receiver module with heading capability</a><ul><li>All-band all constellation GNSS receiver</li><li>All-in-view satellite tracking: multi-constellation, quad-band GNSS module receiver</li><li>Full raw data with positioning measurements and Galileo HAS positioning service compatibility</li><li>Best-in-class RTK cm-level positioning accuracy</li><li>Advanced GNSS+ algorithms</li><li>20Hz update rate</li></ul></li><li><a href="https://www.st.com/en/mems-and-sensors/iis2mdc.html" target="_blank" rel="noreferrer">ST IIS2MDC Magnetometer</a></li><li><a href="https://www.bosch-sensortec.com/en/products/environmental-sensors/pressure-sensors/bmp390/" target="_blank" rel="noreferrer">Bosch BMP390 Barometer</a></li><li><a href="https://www.invensense.tdk.com/en-us/products/6-axis/icm-42688-p" target="_blank" rel="noreferrer">Invensense ICM-42688-P 6-Axis IMU</a></li></ul></li><li>STM32F412VGH6 MCU</li><li>Кнопка безпеки</li><li>Зумер</li><li>Two CAN Connectors (Pixhawk Connector Standard 4-pin JST GH)</li><li>G5 &quot;UART 2&quot; Connector <ul><li>4-pin JST GH</li><li>TX, RX, PPS, GND</li></ul></li><li>G5 USB C</li><li>Debug Connector (Pixhawk Connector Standard 6-pin JST SH)</li><li>LED індикатори <ul><li>GPS Fix</li><li>Статус RTK</li><li>RGB Статус системи</li></ul></li><li>USA Built</li><li>NDAA Compliant</li><li>Вимоги до живлення <ul><li>5V <ul><li>270mA</li></ul></li></ul></li><li>Розміри <ul><li>Without Antenna <ul><li>48.0mm x 40.0mm x 15.4mm</li><li>13.0g</li></ul></li><li>With Antenna <ul><li>48.0mm x 40.0mm x 51.0mm</li><li>43.5g</li></ul></li></ul></li><li>Includes <ul><li>CAN Cable (Pixhawk Connector Standard 4-pin)</li><li>Full-Frequency Helical GPS Antenna</li></ul></li></ul><h2 id="налаштування-програмного-забезпечення" tabindex="-1">Налаштування програмного забезпечення <a class="header-anchor" href="#налаштування-програмного-забезпечення" aria-label="Permalink to &quot;Налаштування програмного забезпечення&quot;">​</a></h2><h3 id="підключення" tabindex="-1">Підключення <a class="header-anchor" href="#підключення" aria-label="Permalink to &quot;Підключення&quot;">​</a></h3><p>The ARK G5 RTK HEADING GPS is connected to the CAN bus using a <a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-009%20Pixhawk%20Connector%20Standard.pdf" target="_blank" rel="noreferrer">Pixhawk connector standard</a> 4-pin JST GH cable. For more information, refer to the <a href="./../can/#wiring">CAN Wiring</a> instructions.</p><h3 id="встановлення" tabindex="-1">Встановлення <a class="header-anchor" href="#встановлення" aria-label="Permalink to &quot;Встановлення&quot;">​</a></h3><p>The recommended mounting orientation is with the connectors on the board pointing towards the <strong>back of vehicle</strong>.</p><p>The sensor can be mounted anywhere on the frame, but you will need to specify its position, relative to vehicle centre of gravity, during <a href="#px4-configuration">PX4 configuration</a>.</p><h2 id="налаштування-прошивки" tabindex="-1">Налаштування прошивки <a class="header-anchor" href="#налаштування-прошивки" aria-label="Permalink to &quot;Налаштування прошивки&quot;">​</a></h2><p>The Septentrio G5 module firmware can be updated using the Septentrio <a href="https://www.septentrio.com/en/products/gps-gnss-receiver-software/rxtools" target="_blank" rel="noreferrer">RxTools</a> application.</p><h2 id="налаштування-польотного-контролера" tabindex="-1">Налаштування польотного контролера <a class="header-anchor" href="#налаштування-польотного-контролера" aria-label="Permalink to &quot;Налаштування польотного контролера&quot;">​</a></h2><h3 id="увімкнення-dronecan" tabindex="-1">Увімкнення DroneCAN <a class="header-anchor" href="#увімкнення-dronecan" aria-label="Permalink to &quot;Увімкнення DroneCAN&quot;">​</a></h3><p>In order to use the ARK G5 RTK HEADING GPS, connect it to the Pixhawk CAN bus and enable the DroneCAN driver by setting parameter <a href="./../advanced_config/parameter_reference#UAVCAN_ENABLE">UAVCAN_ENABLE</a> to <code>2</code> for dynamic node allocation (or <code>3</code> if using <a href="./../dronecan/escs">DroneCAN ESCs</a>).</p><p>Кроки наступні:</p><ul><li>In <em>QGroundControl</em> set the parameter <a href="./../advanced_config/parameter_reference#UAVCAN_ENABLE">UAVCAN_ENABLE</a> to <code>2</code> or <code>3</code> and reboot (see <a href="./../advanced_config/parameters">Finding/Updating Parameters</a>).</li><li>Connect ARK G5 RTK HEADING GPS CAN to the Pixhawk CAN.</li></ul><p>Після активації модуль буде виявлено при завантаженні.</p><p>There is also CAN built-in bus termination via <a href="./../advanced_config/parameter_reference#CANNODE_TERM">CANNODE_TERM</a></p><h3 id="конфігурація-px4" tabindex="-1">Конфігурація PX4 <a class="header-anchor" href="#конфігурація-px4" aria-label="Permalink to &quot;Конфігурація PX4&quot;">​</a></h3><p>You need to set necessary <a href="./">DroneCAN</a> parameters and define offsets if the sensor is not centred within the vehicle:</p><ul><li>Enable GPS yaw fusion by setting bit 3 of <a href="./../advanced_config/parameter_reference#EKF2_GPS_CTRL">EKF2_GPS_CTRL</a> to true.</li><li>Enable GPS blending to ensure the heading is always published by setting <a href="./../advanced_config/parameter_reference#SENS_GPS_MASK">SENS_GPS_MASK</a> to 7 (all three bits checked).</li><li>Enable <a href="./../advanced_config/parameter_reference#UAVCAN_SUB_GPS">UAVCAN_SUB_GPS</a>, <a href="./../advanced_config/parameter_reference#UAVCAN_SUB_MAG">UAVCAN_SUB_MAG</a>, and <a href="./../advanced_config/parameter_reference#UAVCAN_SUB_BARO">UAVCAN_SUB_BARO</a>.</li><li>The parameters <a href="./../advanced_config/parameter_reference#SENS_GPS0_OFFX">SENS_GPS0_OFFX</a>, <a href="./../advanced_config/parameter_reference#SENS_GPS0_OFFY">SENS_GPS0_OFFY</a> and <a href="./../advanced_config/parameter_reference#SENS_GPS0_OFFZ">SENS_GPS0_OFFZ</a> can be set to account for the offset of the ARK G5 RTK HEADING GPS from the vehicle&#39;s centre of gravity.</li></ul><h3 id="parameter-references" tabindex="-1">Parameter references <a class="header-anchor" href="#parameter-references" aria-label="Permalink to &quot;Parameter references&quot;">​</a></h3><p>This GPS is using ARK&#39;s private driver, the parameters below only exist on the firmware we ship the GPS with. You can set these params either in QGC or using the DroneCAN GUI Tool.</p><h4 id="sep-offs-yaw-float" tabindex="-1">SEP_OFFS_YAW (float) <a class="header-anchor" href="#sep-offs-yaw-float" aria-label="Permalink to &quot;SEP_OFFS_YAW (float)&quot;">​</a></h4><p>Heading offset angle for dual antenna GPS setups that support heading estimation. Set this to 0 if the antennas are parallel to the forward-facing direction of the vehicle and the Rover/ANT2 antenna is in front. The offset angle increases clockwise. Set this to 90 if the ANT2 antenna is placed on the right side of the vehicle and the Moving Base/MAIN antenna is on the left side.</p><ul><li>Default: 0</li><li>Min: -360</li><li>Max: 360</li><li>Unit: degree</li></ul><h4 id="sep-offs-pitch-float" tabindex="-1">SEP_OFFS_PITCH (float) <a class="header-anchor" href="#sep-offs-pitch-float" aria-label="Permalink to &quot;SEP_OFFS_PITCH (float)&quot;">​</a></h4><p>Vertical offsets can be compensated for by adjusting the Pitch offset. Note that this can be interpreted as the &quot;roll&quot; angle in case the antennas are aligned along the perpendicular axis. This occurs in situations where the two antenna ARPs may not be exactly at the same height in the vehicle reference frame. Since pitch is defined as the right-handed rotation about the vehicle Y axis, a situation where the main antenna is mounted lower than the aux antenna (assuming the default antenna setup) will result in a positive pitch.</p><ul><li>Default: 0</li><li>Min: -90</li><li>Max: 90</li><li>Unit: degree</li></ul><h4 id="sep-out-rate-enum" tabindex="-1">SEP_OUT_RATE (enum) <a class="header-anchor" href="#sep-out-rate-enum" aria-label="Permalink to &quot;SEP_OUT_RATE (enum)&quot;">​</a></h4><p>Configures the output rate for GNSS data messages.</p><ul><li>-1: OnChange (Default)</li><li>50: 50 ms</li><li>100: 100 ms</li><li>200: 200 ms</li><li>500: 500 ms</li></ul><h2 id="значення-led-індикаторів" tabindex="-1">Значення LED індикаторів <a class="header-anchor" href="#значення-led-індикаторів" aria-label="Permalink to &quot;Значення LED індикаторів&quot;">​</a></h2><p>The GPS status lights are located to the right of the connectors:</p><ul><li>Миготіння зеленого - це фіксація GPS</li><li>Миготіння синього - це отримані корекції та RTK Float</li><li>Сталий синій - це RTK зафіксовано</li></ul><h2 id="дивіться-також" tabindex="-1">Дивіться також <a class="header-anchor" href="#дивіться-також" aria-label="Permalink to &quot;Дивіться також&quot;">​</a></h2><ul><li><a href="https://docs.arkelectron.com/gps/ark-g5-rtk-gps" target="_blank" rel="noreferrer">ARK G5 RTK HEADING GPS Documentation</a> (ARK Docs)</li></ul>',44)])])}const _=t(l,[["render",o]]);export{m as __pageData,_ as default};
